CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"phone" TEXT,"slug" TEXT NOT NULL,"logoUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"priceCents" INTEGER NOT NULL,"imageUrl" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"categoryId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Product_pkey" PRIMARY KEY("id"));
CREATE TABLE "Customer" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"notes" TEXT,"publicToken" TEXT,"linkActive" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Customer_pkey" PRIMARY KEY("id"));
CREATE TABLE "CustomerPrice" ("id" TEXT NOT NULL,"customerId" TEXT NOT NULL,"productId" TEXT NOT NULL,"priceCents" INTEGER NOT NULL,CONSTRAINT "CustomerPrice_pkey" PRIMARY KEY("id"));
CREATE TABLE "PasswordReset" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),CONSTRAINT "PasswordReset_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_slug_key" ON "User"("slug"); CREATE UNIQUE INDEX "Category_userId_name_key" ON "Category"("userId","name"); CREATE UNIQUE INDEX "Customer_publicToken_key" ON "Customer"("publicToken"); CREATE UNIQUE INDEX "CustomerPrice_customerId_productId_key" ON "CustomerPrice"("customerId","productId"); CREATE UNIQUE INDEX "PasswordReset_tokenHash_key" ON "PasswordReset"("tokenHash");
CREATE INDEX "Product_userId_active_idx" ON "Product"("userId","active"); CREATE INDEX "Product_categoryId_idx" ON "Product"("categoryId"); CREATE INDEX "Customer_userId_name_idx" ON "Customer"("userId","name"); CREATE INDEX "PasswordReset_expiresAt_idx" ON "PasswordReset"("expiresAt");
ALTER TABLE "Category" ADD CONSTRAINT "Category_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Product" ADD CONSTRAINT "Product_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Customer" ADD CONSTRAINT "Customer_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CustomerPrice" ADD CONSTRAINT "CustomerPrice_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CustomerPrice" ADD CONSTRAINT "CustomerPrice_productId_fkey" FOREIGN KEY("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PasswordReset" ADD CONSTRAINT "PasswordReset_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
